import{_ as t,o as a,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const r="/assets/ui-minimalist-option.BHhOBuwZ.png",g=JSON.parse('{"title":"FAQ","description":"Réponses aux questions fréquentes sur UI eXtension.","frontmatter":{"description":"Réponses aux questions fréquentes sur UI eXtension.","hide":["toc","navigation"]},"headers":[],"relativePath":"fr/projects/uix/faq.md","filePath":"fr/projects/uix/faq.md","lastUpdated":1793447386000}'),i={name:"fr/projects/uix/faq.md"};function d(o,e,l,c,u,m){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="comment-migrer-au-mieux-depuis-card-mod" tabindex="-1">Comment migrer au mieux depuis Card-mod ? <a class="header-anchor" href="#comment-migrer-au-mieux-depuis-card-mod" aria-label="Permalink to &quot;Comment migrer au mieux depuis Card-mod ?&quot;">​</a></h2><ul><li>Désinstallez Card-mod.</li><li>Si vous utilisez <code>extra_module_url</code> pour charger la ressource Card-mod, supprimez cette entrée et redémarrez Home Assistant.</li><li>Suivez ensuite le <a href="./quick-start">guide de démarrage rapide de UI eXtension</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">&quot;Ajouter UI eXtension comme service&quot;</p><p>UI eXtension est une intégration. Après l&#39;avoir installée avec HACS, vous devez l&#39;ajouter comme service. Ne sautez pas l&#39;étape <strong>Ajouter le service UI eXtension</strong> ; elle peut facilement passer inaperçue si vous n&#39;avez pas l&#39;habitude d&#39;ajouter des intégrations comme services.</p></div><details class="details custom-block"><summary>UI Lovelace Minimalist peut charger la ressource Card-mod</summary><p>Si UI Lovelace Minimalist est installé, il peut charger la ressource Card-mod. En raison de l&#39;ordre de chargement des intégrations, UI eXtension ne peut pas détecter ce conflit. Pour continuer à utiliser UI Lovelace Minimalist avec UI eXtension, désactivez l&#39;option <code>Include custom card resources it&#39;s depending on</code> dans sa configuration, puis chargez les cartes personnalisées nécessaires avec HACS ou manuellement.</p><p><img src="'+r+'" alt="UI Minimalist custom card option"></p></details><h2 id="ui-extension-peut-il-remplacer-card-mod-directement" tabindex="-1">UI eXtension peut-il remplacer Card-mod directement ? <a class="header-anchor" href="#ui-extension-peut-il-remplacer-card-mod-directement" aria-label="Permalink to &quot;UI eXtension peut-il remplacer Card-mod directement ?&quot;">​</a></h2><p>Oui. UI eXtension remplace directement Card-mod jusqu&#39;à la version 4.2.1 et prend en charge les configurations de cartes et de thèmes Card-mod. Il est conseillé d&#39;adopter <code>uix:</code> dans les cartes et <code>uix-&lt;thing&gt;(-yaml)</code> dans les thèmes, mais ce changement n&#39;est pas obligatoire.</p><h2 id="ui-extension-est-il-simplement-card-mod-avec-une-documentation-differente" tabindex="-1">UI eXtension est-il simplement Card-mod avec une documentation différente ? <a class="header-anchor" href="#ui-extension-est-il-simplement-card-mod-avec-une-documentation-differente" aria-label="Permalink to &quot;UI eXtension est-il simplement Card-mod avec une documentation différente ?&quot;">​</a></h2><p>Non. Le code de UI eXtension a évolué pour faire de UIX le domaine et la clé de configuration principaux. Les clés Card-mod restent prises en charge, mais <code>uix:</code> est prioritaire.</p><details class="details custom-block"><summary>Différences entre UI eXtension et Card-mod</summary><ul><li>La clé de configuration des cartes est <code>uix:</code>.</li><li>La clé des thèmes est <code>uix-theme:</code>.</li><li>Les clés de thème <code>thing</code> sont <code>uix-&lt;thing&gt;(-yaml):</code>.</li><li>Le nœud HTML de UI eXtension est <code>&lt;uix-node&gt;</code> ; ses propriétés se rapportent toutes à <code>uix</code>.</li><li>Vous pouvez utiliser <code>{# uix.debug #}</code> pour déboguer les modèles.</li><li>Tous les messages de débogage de la console commencent par <code>UIX</code>.</li></ul></details><h2 id="existe-t-il-une-liste-des-differences-entre-card-mod-et-ui-extension" tabindex="-1">Existe-t-il une liste des différences entre Card-mod et UI eXtension ? <a class="header-anchor" href="#existe-t-il-une-liste-des-differences-entre-card-mod-et-ui-extension" aria-label="Permalink to &quot;Existe-t-il une liste des différences entre Card-mod et UI eXtension ?&quot;">​</a></h2><p>Oui, consultez le tableau ci-dessous.</p><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th style="text-align:center;">Card-mod</th><th style="text-align:center;">UIX</th></tr></thead><tbody><tr><td>Charge correctement les variables de thème <code>...-yaml</code></td><td style="text-align:center;">❌<br>Depuis 2026.8.0</td><td style="text-align:center;">Oui</td></tr><tr><td>Gère correctement la variable de thème <code>...-more-info(-yaml)</code></td><td style="text-align:center;">❌<br>Depuis 2026.3.0</td><td style="text-align:center;">Oui</td></tr><tr><td>Adapte correctement les dialogues pour la variable de thème <code>...-dialog(-yaml)</code></td><td style="text-align:center;">❌<br>Depuis 2026.3.0</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./concepts/dom#outils-d-inspection-du-dom">Outils d&#39;inspection du DOM</a></td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./concepts/dom#selection-de-chemin-hote-element">Sélection de chemin hôte/élément</a></td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./concepts/dom#selecteur-de-recherche-rapide">Sélecteur de recherche rapide</a></td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./forge/">Forge</a> (élément Lovelace personnalisé)</td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./forge/foundries">Fonderies</a> (configurations Forge réutilisables)</td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./using/templates#macros">Macros</a> (modèles Jinja réutilisables)</td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./forge/sparks/">Sparks</a> (comportements autonomes ajoutés aux éléments Forge)</td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./broker/">Broker</a> pour les interactions déclaratives du frontend</td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./extras/frontend-states-throttling">Limitation des mises à jour d&#39;état du frontend</a> (facultative)</td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./extras/dialog-styling-delay">Délai d&#39;application des styles aux dialogues</a> (facultatif)</td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./using/view-backgrounds">Arrière-plans des vues du tableau de bord</a></td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./using/section-backgrounds">Arrière-plans des sections</a></td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./using/view-backgrounds">Arrière-plans des vues</a></td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./using/icons#definir-une-surcharge-pour-une-entite">Style des icônes — remplacement par entité</a></td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./using/images">Style des images d&#39;entité</a></td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./using/custom-panels">Style des panneaux personnalisés</a>, y compris dans des iFrames</td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td><a href="./using/apps">Style des panneaux d&#39;applications et d&#39;Ingress</a>, y compris dans des iFrames</td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td>Fenêtre contextuelle pour recharger ou vider le cache</td><td style="text-align:center;">Non</td><td style="text-align:center;">Oui</td></tr><tr><td>Documentation détaillée avec exemples visuels</td><td style="text-align:center;">Limitée</td><td style="text-align:center;">Oui</td></tr><tr><td>Mod-card</td><td style="text-align:center;">Oui</td><td style="text-align:center;">Oui</td></tr><tr><td>Styles CSS dans les thèmes</td><td style="text-align:center;">Oui</td><td style="text-align:center;">Oui</td></tr><tr><td>Service/action de rechargement ou d&#39;effacement du cache</td><td style="text-align:center;">Oui</td><td style="text-align:center;">Oui</td></tr><tr><td>Fournit des variables (par exemple l&#39;utilisateur actuel)</td><td style="text-align:center;">Oui</td><td style="text-align:center;">Oui</td></tr><tr><td>Styles CSS</td><td style="text-align:center;">Oui</td><td style="text-align:center;">Oui</td></tr><tr><td>URL de ressource</td><td style="text-align:center;">Oui</td><td style="text-align:center;">S.O.</td></tr></tbody></table><h2 id="ui-extension-rencontre-t-il-des-problemes-d-url-de-ressource" tabindex="-1">UI eXtension rencontre-t-il des problèmes d&#39;URL de ressource ? <a class="header-anchor" href="#ui-extension-rencontre-t-il-des-problemes-d-url-de-ressource" aria-label="Permalink to &quot;UI eXtension rencontre-t-il des problèmes d&#39;URL de ressource ?&quot;">​</a></h2><p>Non. En tant qu&#39;intégration, UI eXtension gère directement ses URL de ressources. Aucune intervention n&#39;est nécessaire pour garantir son bon fonctionnement. UI eXtension ajoute dynamiquement sa ressource frontend <code>uix.js</code> comme module supplémentaire et ajoute également une ressource de tableau de bord si vous utilisez CAST. À chaque chargement de l&#39;intégration, UI eXtension ajoute automatiquement sa version à ces ressources.</p><h2 id="faut-il-vider-manuellement-le-cache-des-navigateurs-et-des-applications-mobiles-apres-une-mise-a-jour-de-ui-extension" tabindex="-1">Faut-il vider manuellement le cache des navigateurs et des applications mobiles après une mise à jour de UI eXtension ? <a class="header-anchor" href="#faut-il-vider-manuellement-le-cache-des-navigateurs-et-des-applications-mobiles-apres-une-mise-a-jour-de-ui-extension" aria-label="Permalink to &quot;Faut-il vider manuellement le cache des navigateurs et des applications mobiles après une mise à jour de UI eXtension ?&quot;">​</a></h2><p>Non. Lorsque UI eXtension détecte qu&#39;un rechargement est nécessaire pour vider les caches, un message temporaire s&#39;affiche avec le bouton <code>Reload Now</code>. La page se recharge automatiquement après 60 secondes.</p><p>::: note Le code de rechargement automatique est inclus depuis la version 8.1.0, mais il ne sera disponible qu&#39;après votre prochaine mise à jour. Lors de l&#39;installation de la version 8.1.0, l&#39;appareil utilise encore le code de la version 8.0.1, qui ne comporte pas cette fonction.</p><p>:::</p><h2 id="peut-on-desactiver-le-message-de-rechargement" tabindex="-1">Peut-on désactiver le message de rechargement ? <a class="header-anchor" href="#peut-on-desactiver-le-message-de-rechargement" aria-label="Permalink to &quot;Peut-on désactiver le message de rechargement ?&quot;">​</a></h2><p>Non. Le message garantit que le code JavaScript UIX du frontend correspond à la version de l&#39;intégration. Il apparaît lorsque UIX a changé et que Home Assistant a redémarré, mais que le navigateur utilise encore un bundle UIX en cache d&#39;une autre version.</p><p>La page se recharge automatiquement après 60 secondes, afin que les kiosques sans surveillance actualisent aussi leur frontend.</p><div class="info custom-block"><p class="custom-block-title">Aperçu : UIX 9.0.0-beta.0</p><p>La branche <code>dev</code> actuelle continue à servir la version UIX chargée au démarrage jusqu&#39;au prochain redémarrage de Home Assistant. Après une mise à jour, redémarrez Home Assistant lorsque vous souhaitez activer la nouvelle version. L&#39;ancienne demande de redémarrage immédiat adressée aux administrateurs en raison d&#39;un frontend mis à jour trop tôt disparaît. Ce comportement ne fait pas partie de la base stable 8.4.0.</p></div><h2 id="comment-desinstaller-ui-extension" tabindex="-1">Comment désinstaller UI eXtension ? <a class="header-anchor" href="#comment-desinstaller-ui-extension" aria-label="Permalink to &quot;Comment désinstaller UI eXtension ?&quot;">​</a></h2><p>La désinstallation de UI eXtension se déroule en deux étapes. Supprimez d&#39;abord son entrée de service dans <strong>Appareils et services</strong>. Désinstallez ensuite l&#39;intégration avec HACS ou, si vous l&#39;avez installée manuellement, en supprimant le dossier <code>uix</code> du répertoire <code>custom_components</code>.</p>',25)])])}const h=t(i,[["render",d]]);export{g as __pageData,h as default};
